import{H as e,V as t,et as n,j as r}from"./chunks/framework.Dj60FFN6.js";var i=JSON.parse(`{"title":"Postulati iniziali","description":"","frontmatter":{},"headers":[],"relativePath":"lezioni/b_aritmetica-e-numeri/bf/bfac.md","filePath":"lezioni/b_aritmetica-e-numeri/bf/bfac.md"}`),a={name:`lezioni/b_aritmetica-e-numeri/bf/bfac.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="postulati-iniziali" tabindex="-1">Postulati iniziali <a class="header-anchor" href="#postulati-iniziali" aria-label="Permalink to “Postulati iniziali”">​</a></h1><p>Qualunque teoria matematica parte sempre da alcuni enti fondamentali e dalle relazioni esistenti fra gli stessi: i postulati</p><p>Ad esempio nella Geometria Euclidea del piano abbiamo come enti fondamentali il punto, la retta e il piano e come postulati i seguenti:</p><ul><li>esistenza</li><li>appartenenza</li><li>uguaglianza</li><li>ordine</li><li>parallele</li></ul><p><a href="./../../f/fb/fbb.html">se vuoi vedere i postulati</a></p><p>In Aritmetica invece si parte dai concetti di numero e successivo di un numero e dai postulati (assiomi) di Peano:</p><ul><li>L&#39;unità è un numero</li><li>Il successivo di un numero è ancora un numero</li><li>Dati due numeri, se i loro successivi sono uguali allora i due numeri sono uguali</li><li>L&#39;unità non è successivo di nessun numero</li><li>Se <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>s</mi></mrow><annotation encoding="application/x-tex">s</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.4306em;"></span><span class="mord mathnormal">s</span></span></span></span> è una classe di numeri contenente l&#39;unità e se la classe dei successivi degli elementi di <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>s</mi></mrow><annotation encoding="application/x-tex">s</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.4306em;"></span><span class="mord mathnormal">s</span></span></span></span> è contenuta in <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>s</mi></mrow><annotation encoding="application/x-tex">s</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.4306em;"></span><span class="mord mathnormal">s</span></span></span></span> allora ogni numero è contenuto in <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>s</mi></mrow><annotation encoding="application/x-tex">s</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.4306em;"></span><span class="mord mathnormal">s</span></span></span></span> (principio di induzione)</li></ul><blockquote><p><strong>Nota:</strong> Caratteristica formale dei postulati è che debbono essere fra loro indipendenti e il loro numero deve essere il minore possibile. È logico che cambiando i postulati varia il tipo di matematica che si ottiene, così in geometria, variando il quinto postulato (di Euclide), otteniamo altre geometrie, diverse dalla Geometria Euclidea.</p></blockquote>`,8)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};